fn is_sorted(xs: List[Int]) -> Bool
  requires (len(xs) >= 0)
  ensures ((result and sorted(xs)) or ((not result) and (not sorted(xs))))
  effects pure
  example (is_sorted([1, 2, 2, 5]) == true)
  example (is_sorted([3, 1]) == false)
  example (is_sorted([]) == true)
  example (is_sorted([7]) == true)
  example (is_sorted([1, 3, 2]) == false)
{
  match xs {
    [] => true
    [h, ..t] => match t {
      [] => true
      [k, ..r] => (h <= k) and is_sorted(t)
    }
  }
}

